fn test_kms_gen_key_create_key(client: &aws_sdk_kms::Client) -> Test {
    Test {
        call: Call {
            op: "CreateKey",
            params: scenario::lit(::serde_json::json!({"Description": "compat-scenario key, initial description", "KeySpec": "SYMMETRIC_DEFAULT", "KeyUsage": "ENCRYPT_DECRYPT"})),
            export: vec![
                ("key.arn", "$.KeyMetadata.Arn"),
                ("key.id", "$.KeyMetadata.KeyId"),
            ],
            invoke: {
                let client = client.clone();
                scenario::invoker(move |_b| {
                    let client = client.clone();
                    Box::pin(async move {
                        let capture = scenario::Capture::new();
                        let request = client
                            .create_key()
                            .description("compat-scenario key, initial description")
                            .key_spec(aws_sdk_kms::types::KeySpec::from("SYMMETRIC_DEFAULT"))
                            .key_usage(aws_sdk_kms::types::KeyUsageType::from("ENCRYPT_DECRYPT"))
                            .customize()
                            .interceptor(capture.clone());
                        Ok(scenario::observe(request.send().await, &capture))
                    })
                })
            },
        },
        assert: vec![
            scenario::response_field(vec![
                scenario::non_empty("$.KeyMetadata.Arn"),
                scenario::non_empty("$.KeyMetadata.KeyId"),
            ]),
            scenario::eventually(6, 500,
                scenario::readback(
                    Call {
                        op: "DescribeKey",
                        params: scenario::map(vec![
                            ("KeyId", scenario::context("key.id")),
                        ]),
                        export: Vec::new(),
                        invoke: {
                            let client = client.clone();
                            scenario::invoker(move |b| {
                                let client = client.clone();
                                Box::pin(async move {
                                    let capture = scenario::Capture::new();
                                    let request = client
                                        .describe_key()
                                        .key_id(b.string("KeyId")?)
                                        .customize()
                                        .interceptor(capture.clone());
                                    Ok(scenario::observe(request.send().await, &capture))
                                })
                            })
                        },
                    },
                    vec![
                        scenario::equals("$.KeyMetadata.Arn", scenario::context("key.arn")),
                        scenario::equals("$.KeyMetadata.Description", scenario::lit(::serde_json::json!("compat-scenario key, initial description"))),
                    ],
                ),
            ),
        ],
    }
}

